document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".site-header__menu"),t=document.querySelector(".site-header__nav");e&&t&&(e.addEventListener("click",()=>{e.classList.contains("js-open")?(e.classList.remove("js-open"),t.classList.remove("js-open"),e.setAttribute("aria-expanded","false")):(e.classList.add("js-open"),t.classList.add("js-open"),e.setAttribute("aria-expanded","true"))}),e.setAttribute("aria-expanded","false"))});